use typst::diag::{FileError, FileResult};
use typst::foundations::{Bytes, Datetime, Duration};
use typst::syntax::{FileId, RootedPath, Source, VirtualPath, VirtualRoot};
use typst::text::{Font, FontBook};
use typst::utils::LazyHash;
use typst::{Library, LibraryExt, World};
use typst_layout::PagedDocument;

/// 一个只包含单个内联字符串源码的最小 World。
struct TinyWorld {
    library: LazyHash<Library>,
    main: Source,
    fonts: Vec<Font>,
    book: LazyHash<FontBook>,
}

impl TinyWorld {
    fn new(text: &str) -> Self {
        // 用 typst-kit 的内嵌字体提供器收集字体（typst-cli 默认启用 embedded-fonts feature）。
        let fonts: Vec<Font> =
            typst_kit::fonts::embedded().map(|(font, _info)| font).collect();
        let book = LazyHash::new(FontBook::from_fonts(&fonts));
        let id = FileId::new(RootedPath::new(
            VirtualRoot::Project,
            VirtualPath::new("main.typ").unwrap(),
        ));
        Self {
            library: LazyHash::new(Library::builder([typst_svg::FORMAT]).build()),
            main: Source::new(id, text.to_string()),
            fonts,
            book,
        }
    }
}

impl World for TinyWorld {
    fn library(&self) -> &LazyHash<Library> {
        &self.library
    }

    fn book(&self) -> &LazyHash<FontBook> {
        &self.book
    }

    fn main(&self) -> FileId {
        self.main.id()
    }

    fn source(&self, id: FileId) -> FileResult<Source> {
        if id == self.main.id() {
            Ok(self.main.clone())
        } else {
            Err(FileError::NotFound(id.vpath().as_str().into())) // hmm
        }
    }

    fn file(&self, id: FileId) -> FileResult<Bytes> {
        if id == self.main.id() {
            Ok(Bytes::from_string(self.main.clone()))
        } else {
            Err(FileError::NotFound(...))
        }
    }

    fn font(&self, index: usize) -> Option<Font> {
        self.fonts.get(index).cloned()
    }

    fn today(&self, offset: Option<Duration>) -> Option<Datetime> {
        // 与测试套件一样固定时间，保证可复现（这里直接返回 None 也可以）。
        let datetime = Datetime::from_ymd_hms(1970, 1, 1, 12, 0, 0).unwrap();
        typst_kit::datetime::Time::fixed(datetime).unwrap().today(offset)
    }
}

fn main() -> typst::diag::EcoVec..<..> hmm

